-- GST and HSN master: the rate and HSN code for a product name live in the database, not in the apps.
--
-- Version note: the repo already holds V121 (src/main/resources/db/migration). V100 and V101 are gaps, but Flyway
-- (spring.flyway enabled, outOfOrder is off) refuses to start on a database that has applied V121 when a lower, not yet
-- applied version appears. So this is V122 (tables) and V123 (seed rows, generated by generate_seed.py).
--
-- Data shape (see README_GST_MASTER.md next to the CSV files):
--   gst_hsn_rate  one row per HSN code AND condition (packed / loose, price band ...). A code can have several rows.
--                 (hsn, condition_key) is NOT unique in the source file: six pairs repeat (0401, 8301, 8302, 8306, 9613),
--                 so there is no unique constraint on it; row_no keeps the source order and breaks ties.
--   gst_keyword   one row per item name or spelling, pointing to an HSN code. No foreign key: hsn is not unique in
--                 gst_hsn_rate. The seed migration and the admin service check that the code exists instead.
--   gst_rate_card the rate list (0, 0.25, 1.5, 3, 5, 12, 18, 28, 40 ...). Whether billing accepts a rate is NOT stored: the
--                 service computes it from the single list of rates the billing engine can store.
--   gst_master_audit  old and new value of every admin edit (the short line also goes to audit_log through AuditService).

CREATE TABLE gst_hsn_rate (
  id uuid PRIMARY KEY,
  row_no integer NOT NULL,
  hsn text NOT NULL CHECK (hsn ~ '^[0-9]{4}([0-9]{2}([0-9]{2})?)?$'),
  chapter text NOT NULL DEFAULT '',
  tariff_description text NOT NULL DEFAULT '',
  product_description text NOT NULL,
  -- Gujarati name of the item or heading; empty in the delivered data (the CSV has none), editable by the admin
  name_gu text NOT NULL DEFAULT '',
  classification_conditions text NOT NULL DEFAULT '',
  condition_key text NOT NULL DEFAULT 'ANY',
  condition_label text NOT NULL DEFAULT '',
  -- total rate in percent (the IGST rate); CGST and SGST are half each. numeric, never float: 0.25 and 0.125 occur.
  gst_percent numeric(6,3) NOT NULL CHECK (gst_percent >= 0 AND gst_percent <= 100),
  cgst_percent numeric(6,3) NOT NULL DEFAULT 0 CHECK (cgst_percent >= 0),
  sgst_percent numeric(6,3) NOT NULL DEFAULT 0 CHECK (sgst_percent >= 0),
  igst_percent numeric(6,3) NOT NULL DEFAULT 0 CHECK (igst_percent >= 0),
  cess_percent numeric(6,3) NOT NULL DEFAULT 0 CHECK (cess_percent >= 0),
  tax_type text NOT NULL CHECK (tax_type IN ('TAXABLE', 'NIL', 'EXEMPT', 'NON_GST')),
  schedule text NOT NULL DEFAULT '',
  notification_reference text NOT NULL DEFAULT '',
  source_reference text NOT NULL DEFAULT '',
  effective_from date NOT NULL,
  verification_status text NOT NULL CHECK (verification_status IN ('VERIFIED', 'VERIFY_PRODUCT')),
  note text NOT NULL DEFAULT '',
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT gst_hsn_rate_split CHECK (igst_percent = gst_percent AND cgst_percent + sgst_percent = igst_percent)
);

CREATE INDEX gst_hsn_rate_hsn ON gst_hsn_rate (hsn, condition_key, row_no);
CREATE INDEX gst_hsn_rate_active ON gst_hsn_rate (active, verification_status);

CREATE TABLE gst_keyword (
  id uuid PRIMARY KEY,
  row_no integer NOT NULL,
  name text NOT NULL,
  name_gu text NOT NULL DEFAULT '',
  keywords text NOT NULL DEFAULT '',
  hsn text NOT NULL CHECK (hsn ~ '^[0-9]{4}([0-9]{2}([0-9]{2})?)?$'),
  -- blank = let the server choose the row of the HSN; a key forces that row; PRICE = use the price band
  condition_key text NOT NULL DEFAULT '',
  department text NOT NULL DEFAULT '',
  subcategory text NOT NULL DEFAULT '',
  verification_status text NOT NULL CHECK (verification_status IN ('VERIFIED', 'VERIFY_PRODUCT')),
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid
);

CREATE INDEX gst_keyword_hsn ON gst_keyword (hsn);
CREATE INDEX gst_keyword_name_lower ON gst_keyword (lower(name));

CREATE TABLE gst_rate_card (
  id uuid PRIMARY KEY,
  code text NOT NULL UNIQUE,
  sort_order integer NOT NULL DEFAULT 0,
  gst_percent numeric(6,3) NOT NULL CHECK (gst_percent >= 0 AND gst_percent <= 100),
  cgst_percent numeric(6,3) NOT NULL DEFAULT 0,
  sgst_percent numeric(6,3) NOT NULL DEFAULT 0,
  igst_percent numeric(6,3) NOT NULL DEFAULT 0,
  cess_percent numeric(6,3) NOT NULL DEFAULT 0,
  tax_type text NOT NULL CHECK (tax_type IN ('TAXABLE', 'NIL', 'EXEMPT', 'NON_GST')),
  effective_from date,
  effective_to date,
  source_reference text NOT NULL DEFAULT '',
  verification_status text NOT NULL CHECK (verification_status IN ('VERIFIED', 'VERIFY_PRODUCT', 'VERIFY_ENTRY')),
  note text NOT NULL DEFAULT '',
  -- false for a code that is not a selectable rate (GST_SPECIAL_CESS has no fixed percent)
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE gst_master_audit (
  id uuid PRIMARY KEY,
  at timestamptz NOT NULL,
  actor_id uuid,
  action text NOT NULL CHECK (action IN ('CREATE', 'UPDATE', 'DEACTIVATE', 'ACTIVATE')),
  entity text NOT NULL CHECK (entity IN ('HSN_RATE', 'KEYWORD', 'RATE_CARD')),
  entity_id uuid NOT NULL,
  old_value jsonb,
  new_value jsonb
);

CREATE INDEX gst_master_audit_entity ON gst_master_audit (entity, entity_id, at DESC);
CREATE INDEX gst_master_audit_at ON gst_master_audit (at DESC);

-- Fast "contains" search for GET /gst/hsn?q= . Same pattern as V15: skipped (not failed) when the host database does not
-- allow pg_trgm. The in-memory matcher does not need these indexes; they serve the admin list and the review page.
DO $$
BEGIN
  CREATE EXTENSION IF NOT EXISTS pg_trgm;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'pg_trgm is not available (%), GST trigram indexes skipped', SQLERRM;
END $$;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_trgm') THEN
    CREATE INDEX IF NOT EXISTS gst_hsn_rate_desc_trgm ON gst_hsn_rate USING gin (lower(product_description) gin_trgm_ops);
    CREATE INDEX IF NOT EXISTS gst_keyword_name_trgm ON gst_keyword USING gin (lower(name) gin_trgm_ops);
    CREATE INDEX IF NOT EXISTS gst_keyword_keywords_trgm ON gst_keyword USING gin (lower(keywords) gin_trgm_ops);
  END IF;
END $$;
